async function deleteShotFirstImage(target,button,options={}){if(!confirm('删除本镜首图记录？相邻视频共用这张首图，后续生成会重新准备。'))return;button.disabled=true;try{if(typeof flushDisk==='function')await flushDisk();if(typeof diskConflict!=='undefined'&&diskConflict)throw Error('请先读取最新项目后再删除');const pid=data.project_id,r=await frontFetch('/api/shot-frame/delete-first',{project_id:pid,target_id:target.shot_id||target.id,confirm:true});if(data.project_id!==pid)return;Object.assign(data,r.project);if(typeof diskRevision!=='undefined')diskRevision=r.revision;if(typeof lastDiskData!=='undefined')lastDiskData=JSON.stringify(data);if(typeof browserSave==='function')browserSave();if(typeof videoBatchPreview!=='undefined')videoBatchPreview=null;if(options.inline)window.FirstFrameGalleryUI?.update();else render();toast('首图记录已删除，已有视频保留');}catch(e){toast(e.message);}finally{if(button.isConnected)button.disabled=false;}}
async function stopShotFrameGeneration(target,pos,button){const owner=pos==='last'?nextFirstOwner(target):null,actual=owner||target,position=owner?'first':pos,state=shotFrameState(actual,position),id=state.job?.id,projectId=data.project_id;if(!id){toast('当前没有已提交的生图任务');return;}if(button){button.disabled=true;button.textContent='正在停止…';}try{let job=await frontFetch('/api/tools/jobs/'+id+'/cancel',{});if(job.status==='completed')job=await frontFetch('/api/shot-frame/'+id);if(data.project_id!==projectId||state.job?.id!==id)return;state.job=job;if(job.status==='completed'&&job.image_url){state.versions??=[];if(!state.versions.some(v=>v.id===job.id))state.versions.push(job);state.activeId=job.id;}save();render();toast(job.status==='completed'?'任务已完成，已更新图片':'已停止'+(actual.shot_id||actual.id)+'首帧生成');}catch(e){toast(e.message);if(button){button.disabled=false;button.textContent='停止生成';}}}
function nextFirstOwner(target){if(data.shotScript?.endpoint_generation_policy?.strategy!=='next_shot_first')return null;const i=data.shots.findIndex(s=>(s.shot_id||s.id)===(target.shot_id||target.id));return i>=0?data.shots[i+1]||null:null;}
function shotFrameReferenceCards(refs,tags,pos,busy,target){const fixed=shotFramePlan(target,pos).fixed_reference_image;if(fixed)refs=refs.map(r=>r.picture===fixed.picture?{...r,name:shotFramePlan(target,pos).selected_background_name||'固定桌椅构图',item:{id:fixed.version_id,url:fixed.image_url}}:r);
 return '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin:12px 0">'+refs.map(r=>{
 const checked=tags.includes(r.picture),order=refs.filter(x=>tags.includes(x.picture)).findIndex(x=>x.picture===r.picture)+1;
 const resources=r.type==='scene'?(data.scenes||[]):(data.characters||[]),disabled=busy?'disabled':'',attrs=' data-frame-reference-picture="'+esc(r.picture)+'" data-frame-reference-pos="'+pos+'" ';
 const controls='<label>素材类型<select data-frame-reference-field="type"'+attrs+disabled+'><option value="scene" '+(r.type==='scene'?'selected':'')+'>场景</option><option value="character" '+(r.type==='character'?'selected':'')+'>人物</option></select></label><label>选择素材<select data-frame-reference-field="ref_id"'+attrs+disabled+'>'+resources.map(v=>{const id=v.id||v.scene_id||v.character_id;return '<option value="'+esc(id)+'" '+(id===r.ref_id?'selected':'')+'>'+esc(v.name||id)+'</option>';}).join('')+'</select></label><label>图片版本<select data-frame-reference-field="version"'+attrs+disabled+'><option value="">跟随自动布局 / 当前采用版本</option>'+(fixed?.picture===r.picture?'<option value="__fixed_edit_target" selected>'+esc(shotFramePlan(target,pos).selected_background_name||'当前固定参考图')+'</option>':'')+(r.choices?.items||[]).map(v=>'<option value="'+esc(v.id)+'" '+(fixed?.picture!==r.picture&&target?.pictureSelections?.[r.picture]===v.id?'selected':'')+'>'+esc(v.label||v.id)+'</option>').join('')+'</select></label>';
 return '<div style="border:1px solid #405064;border-radius:10px;padding:10px;background:#111b27">'+(r.item?.url?'<a href="'+esc(r.item.url)+'" target="_blank" rel="noopener" aria-label="放大'+esc(r.name)+'参考图"><img src="'+esc(r.item.url)+'" alt="'+esc(r.name)+'参考图" style="width:100%;height:130px;object-fit:contain;background:#090f16;border-radius:6px"></a>':'<div style="height:130px;display:grid;place-items:center">未生成参考图</div>')+controls+'<label style="display:flex;align-items:center;gap:8px;margin-top:8px"><input type="checkbox" data-frame-ref="'+pos+'" data-tag="'+esc(r.picture)+'" style="width:auto" '+(checked?'checked':'')+' '+(busy?'disabled':'')+'>'+esc(r.picture+' · '+r.name)+'</label><small data-frame-ref-order="'+esc(r.picture)+'">'+(checked?'输入图 '+order:'未选用')+'</small></div>';
 }).join('')+'</div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0"><button type="button" data-frame-upload-reference="'+pos+'" '+(busy?'disabled':'')+'>＋ 上传本地参考图</button><input type="file" accept="image/png,image/jpeg,image/webp" multiple hidden data-frame-reference-files="'+pos+'"><small>PNG / JPEG / WebP，每张最大10MB；最多选用16张参考图</small><span data-frame-reference-upload-status="'+pos+'" role="status"></span></div>';
}
const shotMethodNames={first_frame:'仅首帧',first_last_frames:'首尾帧',reference_images:'多图参考'};
const shotFrameBusy=j=>['preparing','queued','running','waiting','saving','disconnected'].includes(j?.status);
function shotFrameState(target,pos){target.frameImages??={};return target.frameImages[pos]??={versions:[],edits:{}};}
function shotFramePlan(target,pos){const state=target.frameImages?.[pos],m=ShotMethods.imageMethod(target,pos);const plan={...(ShotMethods.frame(target,pos)?.[m]||{}),...(state?.edits?.[m]||{})};const editTarget=target.imageEditPolicy?.edit_target_image;if(pos==='first'&&editTarget?.image_url){const slot=target.picture_inputs?.find(r=>r.type==='scene');plan.fixed_reference_image={picture:slot?.picture||slot?.tag,image_url:editTarget.image_url,version_id:editTarget.id};plan.selected_background_name='编辑目标：'+editTarget.owner_id+' 已生成画面';return plan;}const policy=target.backgroundStatePolicy;if(pos==='first'&&policy?.enabled&&policy.manual_image_id){delete plan.fixed_reference_image;plan.selected_background_name='手动选择的场景版本';return plan;}if(pos==='first'&&policy?.enabled){const scene=data.scenes?.find(s=>(s.scene_id||s.id)===policy.scene_id),image=scene?.reference_states?.find(s=>s.state_id===policy.first_state_id&&s.status==='completed'&&s.image_url);if(!image)throw Error('当前分镜需要的场景状态图尚未完成');const slot=target.picture_inputs?.find(r=>r.type==='scene'&&r.ref_id===policy.scene_id);plan.fixed_reference_image={picture:slot?.picture||slot?.tag,image_url:image.image_url,version_id:image.version_id};plan.selected_background_name=image.name;}return plan;}
function shotGenerationVideoPrompt(target){return ShotMethods.prompt(target);}
function shotGenerationInputs(target){
 const mode=ShotMethods.method(target),prompt=shotGenerationVideoPrompt(target);
 if(!prompt?.trim())throw Error('请填写“'+shotMethodNames[mode]+'”的视频提示词；旧JSON没有独立的仅首帧方案');
 const [width,height]=(ShotAspect.video(target,data)).split('x').map(Number);
 const out={video_method:mode,video_quality:target.videoQuality||'pika_flex',prompt,width,height};
 if(mode==='reference_images'){
  const refs=shotResolvedReferences(target);if(!refs.length||refs.some(r=>!r.item))throw Error('请至少选择一张已完成的场景或人物参考图（可以只选人物）');
  out.picture_inputs=refs.map(r=>({picture:r.picture,type:r.type,ref_id:r.ref_id,image_url:r.item.url,version_id:r.item.id}));
 }else{
  for(const pos of mode==='first_frame'?['first']:['first','last']){const owner=pos==='last'?nextFirstOwner(target):null;const job=ShotMethods.selected(owner||target,owner?'first':pos);if(!job?.image_url||job.status!=='completed')throw Error('请先生成并选择'+(pos==='first'?'首帧':'尾帧'));if(ShotAspect.mismatch(job,data))throw Error('所选首尾帧与项目画幅不符，请按项目尺寸重新生成');out[pos+'_frame']={image_url:job.image_url,version_id:job.id};}
  out.picture_inputs=[];
 }
 return out;
}
function shotFrameStatus(job){if(!job)return '尚未生成';const labels={preparing:'准备中',queued:'排队中',running:'生成中',saving:'保存中',waiting:'等待结果',disconnected:'连接中断',completed:'已完成',failed:'失败',cancelled:'已停止'};let text=labels[job.status]||job.status;if(job.execution_device)text+=' · '+(job.execution_device.source==='LightCC'?'LightCC / ':'')+(job.execution_device.name||'设备未记录');if(job.progress?.step!=null)text+=' · '+job.progress.step+'/'+job.progress.total_steps+'步';if(job.error)text+=' · '+job.error;if(job.created_at){const secs=(Date.parse(job.finished_at||new Date().toISOString())-Date.parse(job.created_at))/1000;text+=' · '+(job.finished_at?'耗时':'已用')+videoTime(secs);}const range=job.timing?.remaining_range_seconds;if(shotFrameBusy(job)&&range)text+=' · 预计剩余'+videoTimeRange(range);return text;}
function shotFrameCard(target,pos){const next=pos==='last'?nextFirstOwner(target):null;if(next){const image=ShotMethods.selected(next,'first');return '<section class="card" data-frame-card="last"><h3>尾帧 · 使用 '+esc(next.shot_id)+' 首图</h3>'+(image?.image_url?'<img src="'+esc(image.image_url)+'" style="width:100%;height:260px;object-fit:contain">':'<p>尚未生成下一镜首图，一键生成会自动准备并复用。</p>')+'<p class="subtle">同一张图用于本段结束与下一段开场。</p><button type="button" data-next-first-generate>生成 / 更新下一镜首图</button></section>';}

 const config=ShotMethods.frame(target,pos),state=target.frameImages?.[pos],m=ShotMethods.imageMethod(target,pos),plan=shotFramePlan(target,pos),selected=ShotMethods.selected(target,pos),busy=shotFrameBusy(state?.job),id='sf-'+pos;
 const refs=shotResolvedReferences(target),source=plan.reference_source||'picture_inputs',tags=plan.reference_tags||refs.map(r=>r.picture);
 return '<section class="card" data-frame-card="'+pos+'"><h3>'+(pos==='first'?'首帧':'尾帧')+'</h3>'+(selected?.image_url?'<a href="'+esc(selected.image_url)+'" target="_blank" rel="noopener"><img src="'+esc(selected.image_url)+'" alt="'+(pos==='first'?'首帧':'尾帧')+'预览，点击放大" style="width:100%;height:260px;object-fit:contain;background:#0b1119"></a>':'<div style="height:160px;display:grid;place-items:center;background:#0b1119">待生成</div>')+'<p id="'+id+'-status" role="status" class="subtle">'+esc(shotFrameStatus(state?.job||selected))+'</p>'+((state?.job?.enhanced_prompt||selected?.enhanced_prompt)?'<details><summary>查看优化内容</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(state?.job?.enhanced_prompt||selected?.enhanced_prompt)+'</pre></details>':'')+'<label>图片生成方式<select id="'+id+'-method" '+(busy?'disabled':'')+'><option value="auto">AI 推荐'+(config?' · '+(config.default_method==='image_to_image'?'图生图':'文生图'):' · 旧版未提供')+'</option><option value="text_to_image">文生图</option><option value="image_to_image">图生图</option></select></label><p class="subtle">'+esc(config?.recommendation_reason||'旧版 JSON 未提供两套图片方案，请填写对应提示词。')+'</p><label>当前方式的图片提示词<textarea id="'+id+'-prompt" rows="6" '+(busy?'disabled':'')+'>'+esc(plan.prompt||'')+'</textarea></label><label>负面提示词<textarea id="'+id+'-negative" rows="3" '+(busy?'disabled':'')+'>'+esc(plan.negative_prompt||'')+'</textarea></label>'+(m==='image_to_image'?'<label>图生图参考来源<select id="'+id+'-source" '+(busy?'disabled':'')+'><option value="picture_inputs">场景 / 人物素材（合计最多16张）</option>'+(pos==='last'?'<option value="generated_first_frame">当前已选首帧</option>':'')+'</select></label>'+(source==='picture_inputs'?'<div class="subtle">Qwen-Image-2.1 多图参考 · 40步。按勾选后的输入顺序写“输入图1、2、3、4”或“&lt;image1&gt;”。最多16张，场景和人物可一起使用。</div>'+shotFrameReferenceCards(refs,tags,pos,busy,target):'<p class="subtle">尾帧将参考上方当前采用的首帧；请先完成首帧。</p>'):'')+'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="primary" data-frame-generate="'+pos+'" '+(busy?'disabled':'')+'>'+(busy?'生成中…':'生成'+(pos==='first'?'首帧':'尾帧'))+'</button>'+(busy&&state?.job?.id?'<button data-frame-stop="'+pos+'">停止</button>':'')+shotFrameWorkflowLinks(selected,state?.job)+'</div>'+(pos==='first'&&selected?.image_url?'<button type="button" data-delete-first-image style="color:#e8bcb9;margin-top:8px">删除首图</button>':'')+'<label>已生成版本<select id="'+id+'-version" '+(busy?'disabled':'')+'><option value="">选择版本</option>'+((state?.versions)||[]).map((v,i)=>'<option value="'+esc(v.id)+'">V'+(i+1)+' · '+v.width+'×'+v.height+' · '+esc(new Date(v.finished_at).toLocaleString('zh-CN'))+'</option>').join('')+'</select></label></section>';
}
function shotFrameWorkflowLinks(selected,job){const j=selected||job;if(!j)return '';if(j.source==='imagegen'||j.mode==='imported'||j.source==='external')return '<span class="subtle">外部图片 · 无ComfyUI工作流</span>';const source=j.workflow_url?j:job?.id===j.id?job:null;if(!source?.workflow_url)return '<span class="subtle">此版本未保存ComfyUI工作流</span>';const open=source.workflow_open_url||'/api/open-workflow/'+encodeURIComponent(source.id)+'?kind=tool&port='+Number(source.port||18191);return '<a href="'+esc(open)+'" target="_blank" rel="noopener">打开工作流 ↗</a><a href="'+esc(source.workflow_url)+'" target="_blank" rel="noopener" download>下载工作流</a>';}
function shotFrameSizeChoices(target){return ShotAspect.frames(data);}
function shotPlanReviewMarkup(target){return '';}
function shotMethodsMarkup(target,framesOnly=false){const method=ShotMethods.method(target),plans=ShotMethods.plans(target),busy=videoBusy(target.videoJob),review=ShotMethods.needsReview(target);return '<div id="shotMethodsPanel"><div class="divider"></div><h3>'+(framesOnly?'生成分镜首尾帧':'视频生成方案')+'</h3>'+(!framesOnly?'<label>生成方式<select id="shotMethodChoice" '+(busy?'disabled':'')+'><option value="auto">AI 推荐 · '+shotMethodNames[plans?.default_method||'reference_images']+'</option>'+ShotMethods.methods.map(m=>'<option value="'+m+'">'+shotMethodNames[m]+'</option>').join('')+'</select></label>':'')+'<label>首尾帧图片尺寸（跟随项目画幅）<select id="shotFrameSize">'+shotFrameSizeChoices(target).map((size,i)=>'<option value="'+size+'">'+['小','中','大','2K','4K'][i]+' · '+size.replace('x',' × ')+'</option>').join('')+'</select></label><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;margin:16px 0">'+shotFrameCard(target,'first')+shotFrameCard(target,'last')+'</div>'+(!framesOnly?'<label>'+shotMethodNames[method]+' · 视频提示词<textarea id="shotMethodVideoPrompt" rows="10" '+(busy?'disabled':'')+'>'+esc(shotGenerationVideoPrompt(target))+'</textarea></label><p class="subtle" id="shotMethodReadiness"></p>':'<button id="shotFramesToVideo">进入视频生成，选择仅首帧 / 首尾帧 / 多图参考</button>')+'</div>';}
const shotReferenceUploadsPending=new Set();
function appendUploadedFrameReference(target,pos,asset,name,id){const refs=shotResolvedReferences(target),plan=shotFramePlan(target,pos),tags=plan.reference_tags||refs.map(r=>r.picture);if(tags.length>=16)throw Error('最多选用16张参考图，请先取消勾选不需要的图片');target.picture_inputs??=JSON.parse(JSON.stringify(ShotSchema.bindings(target)));const n=Math.max(0,...target.picture_inputs.map(r=>Number((r.picture||r.tag||'').match(/\d+/)?.[0]||0)))+1,picture='<Picture '+n+'>';const description='参考此图中用户指定的外观、结构和细节，目标画面按本镜提示词生成。';data.characters??=[];data.characters.push({id,character_id:id,name,role:'参考素材',description,prompt:'',multiPrompt:'',versions:[],multi:[],portraitVersions:[],specialReference:true,referenceCategory:'other',referenceLayout:'single',videoIdentityPrompt:description,useExternalReference:true,confirmed:true,singleViews:[{...asset,angle:'external',label:'本地参考图'}],externalReferences:[asset],activeExternalReferenceId:asset.id,special_reference:{enabled:true,category:'other',layout:'single',image_path:asset.image_url,image_prompt_zh:'',video_identity_prompt:description}});target.picture_inputs.push({picture,tag:picture,type:'character',ref_id:id});target.referenceListEdited=true;target.pictureSelections??={};target.pictureSelections[picture]=asset.id;const state=shotFrameState(target,pos);state.edits??={};state.edits.image_to_image??={};state.edits.image_to_image.reference_tags=[...tags,picture];return picture;}
async function uploadFrameReferenceFiles(target,pos,files,status){const project=data.project_id,key=project+':'+(target.shot_id||target.id)+':'+pos;if(shotReferenceUploadsPending.has(key))throw Error('参考图正在上传，请稍候');const tags=shotFramePlan(target,pos).reference_tags||shotResolvedReferences(target).map(r=>r.picture);if(tags.length+files.length>16)throw Error('最多选用16张参考图，请减少文件或先取消勾选');for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择PNG、JPEG或WebP图片');if(file.size>10*1024*1024)throw Error('每张图片不能超过10MB');}shotReferenceUploadsPending.add(key);try{for(const file of files){if(data.project_id!==project)throw Error('项目已切换，请重新选择图片');status.textContent='正在上传 '+file.name+'…';await ensureProjectSaved();const id='SPECIAL_'+crypto.randomUUID(),name=file.name.replace(/\.[^.]+$/,'').slice(0,100)||'本地参考图',image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(file);});const asset=await frontFetch('/api/character-reference-upload',{project_id:project,character_id:id,name,new_reference:true,image,layout:'single'});if(data.project_id!==project)throw Error('图片已保存到原项目，请切回原项目再选择');appendUploadedFrameReference(target,pos,asset,name,id);save();await ensureProjectSaved();}status.textContent='上传完成';}finally{shotReferenceUploadsPending.delete(key);}}
function setShotFrameReference(target,picture,field,value){const r=allShotReferences(target).find(r=>r.picture===picture);if(!r)throw Error('参考图已变化，请重新打开');if(field==='version'){if(value==='__fixed_edit_target')return;if(value&&!r.choices.items.some(v=>v.id===value))throw Error('所选图片版本已不可用');if(r.type==='scene'&&target.imageEditPolicy?.edit_target_image)delete target.imageEditPolicy.edit_target_image;target.pictureSelections??={};if(value)target.pictureSelections[picture]=value;else delete target.pictureSelections[picture];if(r.type==='scene'&&target.backgroundStatePolicy?.enabled){if(value)target.backgroundStatePolicy.manual_image_id=value;else{delete target.backgroundStatePolicy.manual_image_id;const p=target.backgroundStatePolicy,layout=data.scenes?.find(s=>(s.scene_id||s.id)===p.scene_id)?.reference_states?.find(s=>s.state_id===p.first_state_id);if(layout)target.pictureSelections[picture]=layout.version_id;}}return;}if(r.type==='scene'&&target.imageEditPolicy?.edit_target_image)delete target.imageEditPolicy.edit_target_image;target.pictureBindingOverrides??={};const o=target.pictureBindingOverrides[picture]??={type:r.type,ref_id:r.ref_id,enabled:true};if(field==='type'){if(!['scene','character'].includes(value))throw Error('无效素材类型');o.type=value;const item=(value==='scene'?data.scenes:data.characters)?.[0];o.ref_id=item?.id||item?.scene_id||item?.character_id||'';}else if(field==='ref_id'){if(!(r.type==='scene'?data.scenes:data.characters).some(v=>(v.id||v.scene_id||v.character_id)===value))throw Error('所选素材不存在');o.ref_id=value;}else throw Error('无效参考图设置');o.source='library';delete o.library_binding;delete o.usage;delete target.pictureSelections?.[picture];if(r.slot===0)delete target.continuityReference;}
function bindShotMethods(target){
 document.querySelectorAll('[data-frame-upload-reference]').forEach(button=>button.onclick=()=>document.querySelector('[data-frame-reference-files="'+button.dataset.frameUploadReference+'"]').click());
 document.querySelectorAll('[data-frame-reference-files]').forEach(input=>input.onchange=async()=>{const pos=input.dataset.frameReferenceFiles,files=[...input.files];if(!files.length)return;const button=document.querySelector('[data-frame-upload-reference="'+pos+'"]'),status=document.querySelector('[data-frame-reference-upload-status="'+pos+'"]');button.disabled=true;input.disabled=true;try{await uploadFrameReferenceFiles(target,pos,files,status);render();toast('本地参考图已上传并勾选');}catch(e){status.textContent=e.message;toast(e.message);}finally{button.disabled=false;input.disabled=false;input.value='';}});

 document.querySelectorAll('[data-frame-reference-field]').forEach(el=>el.onchange=()=>{try{setShotFrameReference(target,el.dataset.frameReferencePicture,el.dataset.frameReferenceField,el.value);save();render();}catch(e){toast(e.message);}});
 const method=document.querySelector('#shotMethodChoice');if(method){method.value=target.videoMethodOverride||'auto';method.onchange=e=>{target.videoMethodOverride=e.target.value;save();render();};}
 const size=document.querySelector('#shotFrameSize'),choices=shotFrameSizeChoices(target);size.value=choices.includes(target.frameResolution)?target.frameResolution:choices[1];size.onchange=e=>{target.frameResolution=e.target.value;save();};
 document.querySelectorAll('[data-plan-review]').forEach(el=>el.oninput=e=>{ShotMethods.setPrompt(target,el.dataset.planReview,e.target.value);save();updateShotReadiness(target);});
 document.querySelectorAll('[data-plan-accept]').forEach(el=>el.onclick=()=>{try{ShotMethods.accept(target,el.dataset.planAccept);save();render();}catch(e){toast(e.message);}});
 document.querySelector('#shotFramesToVideo')?.addEventListener('click',()=>{tab=2;shotMode='shots';render();});
 const vp=document.querySelector('#shotMethodVideoPrompt');if(vp)vp.oninput=e=>{ShotMethods.setPrompt(target,ShotMethods.method(target),e.target.value);save();updateShotReadiness(target);};
 for(const pos of ['first','last']){
  if(pos==='last'&&nextFirstOwner(target)){document.querySelector('[data-next-first-generate]')?.addEventListener('click',()=>generateShotFrame(nextFirstOwner(target),'first'));continue;}
  const prefix='#sf-'+pos,st=target.frameImages?.[pos];const m=document.querySelector(prefix+'-method');m.value=st?.methodOverride||'auto';m.onchange=e=>{shotFrameState(target,pos).methodOverride=e.target.value;save();render();};
  const edit=(key,value)=>{const state=shotFrameState(target,pos),method=ShotMethods.imageMethod(target,pos);state.edits??={};state.edits[method]??={};state.edits[method][key]=value;save();};
  document.querySelector(prefix+'-prompt').oninput=e=>edit('prompt',e.target.value);document.querySelector(prefix+'-negative').oninput=e=>edit('negative_prompt',e.target.value);
  const source=document.querySelector(prefix+'-source');if(source){source.value=shotFramePlan(target,pos).reference_source||'picture_inputs';source.onchange=e=>{edit('reference_source',e.target.value);edit('reference_tags',e.target.value==='generated_first_frame'?[]:shotResolvedReferences(target).map(r=>r.picture));render();};}
  document.querySelectorAll('[data-frame-ref="'+pos+'"]').forEach(el=>el.onchange=()=>{const selected=[...document.querySelectorAll('[data-frame-ref="'+pos+'"]:checked')].map(e=>e.dataset.tag);edit('reference_tags',selected);document.querySelectorAll('[data-frame-card="'+pos+'"] [data-frame-ref-order]').forEach(label=>{const i=selected.indexOf(label.dataset.frameRefOrder);label.textContent=i<0?'未选用':'输入图 '+(i+1);});});
  const versions=document.querySelector(prefix+'-version');versions.value=ShotMethods.selected(target,pos)?.id||'';versions.onchange=e=>{if(e.target.value){const state=shotFrameState(target,pos);state.activeId=e.target.value;state.needsReview=false;save();render();}};
  document.querySelector('[data-frame-generate="'+pos+'"]').onclick=()=>generateShotFrame(target,pos);
  document.querySelector('[data-frame-accept="'+pos+'"]')?.addEventListener('click',()=>{shotFrameState(target,pos).needsReview=false;save();render();});
  document.querySelector('[data-frame-stop="'+pos+'"]')?.addEventListener('click',e=>stopShotFrameGeneration(target,pos,e.currentTarget));
 }
 document.querySelector('[data-delete-first-image]')?.addEventListener('click',e=>deleteShotFirstImage(target,e.currentTarget));updateShotReadiness(target);
}
function updateShotReadiness(target){const box=document.querySelector('#shotMethodReadiness');if(!box)return;let message='';try{shotGenerationInputs(target);message='素材与提示词已就绪 · '+shotMethodNames[ShotMethods.method(target)];}catch(e){message=e.message;}box.textContent=message;const busy=videoBusy(target.videoJob),batch=typeof videoBatchActive==='function'&&videoBatchActive();let valid=false;try{shotGenerationInputs(target);valid=true;}catch{}for(const id of ['shotVideoGenerate','shotVideoDraft']){const button=document.getElementById(id);if(button)button.disabled=busy||!valid||batch;} }
async function generateShotFrame(target,pos,options={}){
 const projectId=data.project_id,state=shotFrameState(target,pos);if(shotFrameBusy(state.job))return;if(shotReferenceUploadsPending.has(projectId+':'+(target.shot_id||target.id)+':'+pos)){toast('请等待参考图上传完成');return;}
 const plan=shotFramePlan(target,pos),method=ShotMethods.imageMethod(target,pos);if(!plan.prompt?.trim()){toast('请填写当前图片方式的提示词');return;}
 const refs=shotResolvedReferences(target),tags=plan.reference_tags||refs.map(r=>r.picture),selected=refs.filter(r=>tags.includes(r.picture));
 if(method==='image_to_image'&&plan.reference_source!=='generated_first_frame'&&(selected.some(r=>!r.item)||!selected.length||selected.length>16)){toast('图生图需要1–16张已完成的参考图，请检查勾选内容');return;}
 const [width,height]=(ShotAspect.frame(target,data)).split('x').map(Number),requestId=crypto.randomUUID();
 state.job={id:null,request_id:requestId,status:'preparing',created_at:new Date().toISOString()};save();if(options.inline)window.FirstFrameGalleryUI?.update();else render();
 try{if(typeof flushDisk==='function')await flushDisk();const job=await frontFetch('/api/shot-frame',{request_id:requestId,project_id:projectId,target_id:target.shot_id||target.id,position:pos,method,prompt:plan.prompt,negative_prompt:plan.negative_prompt||'',width,height,port:(typeof videoGenerationPort==='function'?videoGenerationPort():8188),reference_source:plan.reference_source||'picture_inputs',first_frame:{image_url:ShotMethods.selected(target,'first')?.image_url},picture_inputs:selected.map(r=>({picture:r.picture,original_picture:r.picture,type:r.type,ref_id:r.ref_id,image_url:plan.fixed_reference_image?.picture===r.picture?plan.fixed_reference_image.image_url:r.item?.url}))});state.job={...job,timing_received_at:Date.now()};if(data.project_id===projectId){if(data.shots?.[si]===target)document.getElementById('shotFrameGeneratorDialog')?.close();save();if(options.inline)window.FirstFrameGalleryUI?.update();else render();toast('已提交'+(pos==='first'?'首帧':'尾帧')+'生成');}}catch(e){state.job={...state.job,status:'failed',error:e.message};if(data.project_id===projectId){save();if(options.inline)window.FirstFrameGalleryUI?.update();else render();toast(e.message);}}
}
const shotMethodsPreviousShots=shots;shots=function(){shotMethodsPreviousShots();const target=shotVideoTarget();if(!target||target.clip_id)return;const panel=document.querySelector('#shotVideoPanel');if(!panel)return;panel.insertAdjacentHTML('afterbegin',shotMethodsMarkup(target));bindShotMethods(target);if(ShotMethods.method(target)==='first_frame')document.querySelector('[data-frame-card=last]').style.display='none';if(ShotMethods.method(target)==='reference_images'){const grid=document.querySelector('#shotMethodsPanel [data-frame-card]')?.parentElement,size=document.querySelector('#shotFrameSize')?.closest('label');if(grid){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='可选：生成首帧 / 首尾帧（多图参考无需先生成）';grid.before(details);details.append(summary);if(size)details.append(size);details.append(grid);}}for(const id of ['hierarchyImagePrompt','hierarchyVideoPrompt','rebuildHierarchyPrompt']){const el=document.getElementById(id);if(el)(el.closest('label')||el).style.display='none';}panel.querySelectorAll('p').forEach(p=>{if(p.textContent.includes('本机 H3 多图参考 · 4 步'))p.textContent='仅首帧 / 首尾帧使用对应端点工作流；多图参考按场景与人物绑定执行。短镜头生成后裁切到计划时长。';});};
const shotMethodsPreviousStage=stage;stage=function(){if(tab!==3){shotMethodsPreviousStage();return;}if(si>=data.shots.length)si=0;const target=data.shots[si];document.querySelector('#panel').innerHTML='<div class="section-head"><div><h3>分镜首尾帧</h3><p>使用 Qwen-Image-2.1 生成单张首帧或首尾两张，支持场景与人物多图参考，采用后用于视频生成。</p></div></div><label>主分镜<select id="shotFrameTarget">'+data.shots.map((s,i)=>'<option value="'+i+'">'+esc((s.shot_id||s.id)+' · '+s.title)+'</option>').join('')+'</select></label>'+(target?shotMethodsMarkup(target,true):'<div class="card">请先导入分镜JSON。</div>');const select=document.querySelector('#shotFrameTarget');select.value=String(si);select.onchange=e=>{si=Number(e.target.value);render();};if(target)bindShotMethods(target);};
let shotFramesPolling=false,shotFrameRecovered='',shotFrameRecoveryAt=0;
setInterval(async()=>{
 if(shotFramesPolling||!data.project_id)return;shotFramesPolling=true;const projectId=data.project_id;let redraw=false,changed=false;
 try{
  if(shotFrameRecovered!==projectId||Date.now()-shotFrameRecoveryAt>20000){const jobs=await frontFetch('/api/shot-frame?project_id='+encodeURIComponent(projectId));if(data.project_id!==projectId)return;for(const job of jobs){const b=job.frame_binding,target=data.shots.find(s=>(s.shot_id||s.id)===b.target_id);if(!target||target.deletedShotFrameIds?.includes(job.id))continue;const state=shotFrameState(target,b.position),known=state.job?.id===job.id||state.job?.request_id===b.request_id,plan=shotFramePlan(target,b.position);if(!known&&job.prompt!==plan.prompt)continue;if(!state.job||state.job.request_id===b.request_id||Date.parse(job.created_at)>Date.parse(state.job.created_at||0)){redraw||=state.job?.status!==job.status||state.job?.id!==job.id;state.job={...job,timing_received_at:Date.now()};changed=true;}}shotFrameRecovered=projectId;shotFrameRecoveryAt=Date.now();}
  for(const target of data.shots||[])for(const pos of ['first','last']){const state=target.frameImages?.[pos];if(!state?.job?.id||(!shotFrameBusy(state.job)&&!(state.job.status==='completed'&&!state.versions?.some(v=>v.id===state.job.id))))continue;const job=await frontFetch('/api/shot-frame/'+state.job.id);if(data.project_id!==projectId)return;redraw||=state.job.status!==job.status;state.job={...job,timing_received_at:Date.now()};changed=true;if(job.status==='completed'&&job.image_url){state.versions??=[];if(!state.versions.some(v=>v.id===job.id)){state.versions.push(job);state.activeId=job.id;state.needsReview=false;redraw=true;}}if(target===data.shots[si]){const status=document.querySelector('#sf-'+pos+'-status');if(status)status.textContent=shotFrameStatus(job);if(typeof updateShotFrameProgress==='function')updateShotFrameProgress(target);}}
  if(changed)save();if(redraw&&[2,3].includes(tab)){if(!['TEXTAREA','INPUT'].includes(document.activeElement?.tagName))render();else updateShotReadiness(data.shots[si]);}
 }catch(e){const box=document.querySelector('#shotMethodReadiness');if(box)box.textContent='状态更新暂时中断：'+e.message;}finally{shotFramesPolling=false;}
},4000);
render();
